from pathlib import Path
p=Path('razync/valean_625.py')
s=p.read_text(encoding='utf-8')
start=s.index('def processar_bb_625(')
end=s.index('\n\ndef processar_sicredi_625', start)
new='''def processar_bb_625(conteudo: bytes) -> pd.DataFrame:\n    texto = _texto_pdf(conteudo)\n    linhas = [re.sub(r"\\s+", " ", x).strip() for x in texto.splitlines()]\n    registros = []\n    moeda = re.compile(r"(\\d{1,3}(?:\\.\\d{3})*,\\d{2})\\s*([CD])", re.I)\n    data_atual = None\n    historico_pendente = []\n\n    for linha in linhas:\n        if not linha or linha.lower().startswith(("https://", "pagina ")):\n            continue\n        data_match = re.match(r"^(\\d{2}/\\d{2}/\\d{4})\\s*(.*)$", linha)\n        if data_match:\n            data_atual = pd.to_datetime(data_match.group(1), dayfirst=True, errors="coerce")\n            corpo = data_match.group(2).strip()\n        elif data_atual is not None:\n            corpo = linha\n        else:\n            continue\n\n        if _normalizar(corpo).startswith(("cliente", "agencia", "conta corrente", "periodo", "lancamentos", "dt.")):\n            continue\n\n        valores = list(moeda.finditer(corpo))\n        if not valores:\n            # No BB a descrição/documento pode quebrar de linha antes do valor.\n            # Guardamos o texto e aguardamos a linha que contém o valor.\n            historico_pendente.append(corpo)\n            continue\n\n        movimento = valores[0]\n        valor = _valor_br(movimento.group(1), movimento.group(2))\n        antes = corpo[:movimento.start()]\n        partes = historico_pendente + [antes]\n        historico_pendente = []\n        historico = " ".join(x for x in partes if x).strip()\n\n        # Remove somente campos estruturais Documento/Lote do BB, nunca o lançamento.\n        historico = re.sub(r"^\\s*\\d{4}\\s+\\d{5,8}\\s*", "", historico)\n        historico = re.sub(r"\\s+(?:\\d[\\d./-]{2,})\\s*$", "", historico).strip()\n        if pd.isna(data_atual) or "saldo" in _normalizar(historico):\n            continue\n        registros.append(_registro("banco_brasil", data_atual, valor, historico))\n\n    return _finalizar(registros, "Banco do Brasil")\n'''
s=s[:start]+new+s[end:]
p.write_text(s,encoding='utf-8')
